def apply(C, W, inverse=False):
    """Apply the handed-over code with clean temporary wires."""
    anc = C.alloc(ANCILLAS)
    wires = list(W) + anc
    for p in (reversed(PRIMS) if inverse else PRIMS):
        if p[0] == "x":
            C.x(wires[p[1]])
        elif p[0] == "cx":
            C.cx(wires[p[1]], wires[p[2]])
        else:
            C.ccx(wires[p[1]], wires[p[2]], wires[p[3]])
    C.free(anc)
